contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: lock time and amount to send to Put
    function run(uint putLock, uint putAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        // ensure this test contract has enough Ether to send
        require(address(this).balance >= putAmount);

        // Observe before-values via public getter
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // Call Put and capture whether it reverted
        bool putReverted;
        c.Put{value: putAmount}(putLock); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            putReverted = true;
        } else {
            putReverted = false;
        }

        // Observe after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General property: If Put did not revert then
        // 1) contract balance increased by exactly putAmount,
        // 2) recorded Acc.balance did not decrease (afterBal >= beforeBal),
        // 3) unlockTime is non-decreasing (afterUnlock >= beforeUnlock).
        assert(putReverted || (
            afterContractBal == beforeContractBal + putAmount
            && afterBal >= beforeBal
            && afterUnlock >= beforeUnlock
        ));
    }

    // accept ETH when Collect sends funds back
    receive() external payable {}
}

